INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:italian_restaurant',true,'Liquor License #',ARRAY['State Alcoholic Beverage Control Board','Local Health Department','Municipal Business Licensing Authority']::text[],ARRAY['healthiest restaurant in the city','guaranteed safe for all allergies','100% allergen-free kitchen','best restaurant in the world','no risk of foodborne illness','fully gluten-free facility']::text[],ARRAY['Menu items and prices subject to change without notice.','Please inform your server of any food allergies or dietary restrictions before ordering.','Consuming raw or undercooked meats, poultry, seafood, shellfish, or eggs may increase your risk of foodborne illness.','Alcohol service subject to state and local laws. Valid ID required. We reserve the right to refuse service.']::text[],true,false,false,ARRAY['Alcohol advertising must comply with state ABC regulations and may not target minors.','Health claims about menu items must not imply medical benefit without substantiation.','Allergy-safe claims must be qualified and not imply a completely allergen-free environment.','Discount promotions involving alcohol may be restricted by state happy hour laws.']::text[])
