INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:plumber',true,'State Plumbing License #',ARRAY['State Plumbing Licensing Board (jurisdiction-specific, e.g., California Contractors State License Board, Texas State Board of Plumbing Examiners)','Local Building Department / Authority Having Jurisdiction (AHJ)','International Association of Plumbing and Mechanical Officials (IAPMO) — code standards','American Society of Sanitary Engineering (ASSE) — backflow certification']::text[],ARRAY['guaranteed to fix any plumbing problem','cheapest plumber in town','licensed in all 50 states','no permit required for this work']::text[],ARRAY['Plumbing work may require permits from your local building department — contractor is responsible for permit compliance','All work performed in accordance with applicable state and local plumbing codes','License number and insurance certificate available upon request','Gas line work is subject to additional state and local safety regulations and may require a separate gas piping license']::text[],false,false,false,ARRAY['Must not advertise services in states where contractor does not hold an active license','Emergency availability claims (e.g., ''24/7'') must reflect actual staffing and response capability','Pricing advertised must reflect final consumer cost or clearly disclose additional fees','Background check and screening claims (e.g., Angi Screened) must link to verifiable third-party certification']::text[])
