INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:restaurant',true,'State Liquor License #',ARRAY['State Alcoholic Beverage Control Board','Local Health Department','City/County Food Safety Authority']::text[],ARRAY['100% safe from allergens','completely allergen-free kitchen','we guarantee no cross-contamination','certified organic (without USDA certification)','best restaurant in [city] (without substantiated award)','healthiest restaurant in town']::text[],ARRAY['Menu items and prices subject to change without notice','Please inform your server of any food allergies or dietary restrictions; we cannot guarantee allergen-free preparation in a shared kitchen','Consuming raw or undercooked meats, poultry, seafood, shellfish, or eggs may increase your risk of foodborne illness','Alcohol service subject to state and local licensing laws; valid ID required']::text[],true,false,false,ARRAY['Alcohol advertising must comply with state ABC board rules and platform-specific alcohol advertising policies','Health claims about menu items must comply with FDA labeling guidelines if printed on menus','''Organic'' claims require USDA NOP certification documentation','Promotions targeting minors with alcohol-adjacent content are prohibited','Calorie posting requirements apply in jurisdictions with menu labeling laws (ACA Section 4205)']::text[])
